import tempfile

import lancedb
from lancedb.index import FTS


def fresh():
    db = lancedb.connect(tempfile.mkdtemp())
    return db.create_table(
        "t",
        data=[
            {"id": 1, "page_content": "hello world", "vector": [0.1, 0.2, 0.3, 0.4]},
            {"id": 2, "page_content": "goodbye world", "vector": [0.4, 0.3, 0.2, 0.1]},
        ],
    )


CASES = [
    ("positional column", lambda t: t.create_index("page_content", config=FTS())),
    (
        "positional + replace",
        lambda t: t.create_index("page_content", config=FTS(), replace=True),
    ),
    ("metric=None", lambda t: t.create_index(metric=None, config=FTS(), vector_column_name="page_content")),
]

for label, fn in CASES:
    t = fresh()
    try:
        fn(t)
        idx = [(i.name, str(i.index_type)) for i in t.list_indices()]
        hits = t.search("hello", query_type="fts").limit(2).to_list()
        print("OK  ", label, "| indices:", idx, "| fts hits:", len(hits))
    except Exception as e:
        print("FAIL", label, "->", type(e).__name__, e)

