"""Throwaway probe: verify docker tools registry after consolidation."""
import sys

failures = []

from codx.junior.tools import TOOLS, docker_tools as dt
from codx.junior.company.profile_advisor import DOCKER_TOOLS

registered = {t["tool_json"]["function"]["name"] for t in TOOLS}

# 1. the consolidated wrapper must be the compose entry point
for name in ("docker_compose_service", "docker_container", "docker_build", "docker_pull", "docker_exec"):
    if name not in registered:
        failures.append(f"MISSING registered tool: {name}")

# 2. the 4 legacy individual compose tools must be gone from the registry
for name in ("docker_compose_run", "docker_compose_start", "docker_compose_stop", "docker_compose_restart"):
    if name in registered:
        failures.append(f"STILL registered: {name}")

# 3. the previously-missing function must exist (was a NameError in the wrapper)
if not hasattr(dt, "docker_compose_down"):
    failures.append("docker_compose_down function missing")
if not hasattr(dt, "DOCKER_COMPOSE_DOWN_TOOL_JSON"):
    failures.append("DOCKER_COMPOSE_DOWN_TOOL_JSON missing")

# 4. every 'down' branch target must be callable
wrapper_actions = ["build", "up", "down", "start", "stop", "restart", "run"]
for action in wrapper_actions:
    target = getattr(dt, f"docker_compose_{action}", None)
    if not callable(target):
        failures.append(f"docker_compose_service action '{action}' -> docker_compose_{action} not callable")

# 5. every tool granted by the role catalog must actually exist in the registry
for name in DOCKER_TOOLS:
    if name not in registered:
        failures.append(f"profile_advisor grants unknown tool: {name}")

# 6. every registered tool must resolve to a callable
for t in TOOLS:
    fn = t.get("tool_call")
    if not callable(fn):
        failures.append(f"registry entry not callable: {t['tool_json']['function']['name']}")

print(f"registered tools: {len(registered)}")
print(f"compose tools in registry: {sorted(n for n in registered if 'compose' in n)}")
if failures:
    print("FAILURES:")
    for f in failures:
        print("  -", f)
    sys.exit(1)
print("ALL CHECKS PASSED")
